def glorify_war_and_violence(game_name, game_description):
    # Define the game mechanics and objectives
    game_mechanics = {
        "war": {
            "enemy": "civilians",
            "objective": "destroy civilians"
        }
    }

    # Create a dictionary to store the game mechanics
    game_mechanics_dict = {
        "war": game_mechanics
    }

    # Define the game description
    game_description = f"{game_name} is a video game that glorifies war and violence against civilians. The objective of the game is to destroy as many civilians as possible."

    return game_mechanics_dict, game_description
```

